<script setup>
import { $api } from '@/utils/api'
const data=ref({devices:[],zones:[],reservations:[],intervals:[],commands:[],alerts:[],settings:null}),busy=ref(false),error=ref(''),tab=ref('schedule'),deviceOpen=ref(false),zoneOpen=ref(false),operationOpen=ref(false),operation=ref('override'),target=ref(null)
const device=reactive({name:'',code:'',provider:'dry_run',network_host:'',network_port:null,use_tls:false,username:'',password:'',enabled:true,dry_run:true})
const zone=reactive({venue_id:null,sport_code_id:null,lighting_device_channel_id:null,name:'',code:'',active:true,automatic_control_enabled:false,provider_mode:'dry_run',pre_start_minutes:10,post_end_minutes:5,minimum_billable_minutes:30,billing_increment_minutes:30,maximum_continuous_on_minutes:240,financial_owner_type:'sport_code',facility_ids:[]})
const op=reactive({state:'on',minutes:30,reason:''}); const money=v=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format((v||0)/100); const label=v=>(v||'').replaceAll('_',' ')
async function load(){busy.value=true;try{data.value=await $api('/lighting')}catch(e){error.value=e?.data?.message||'Lighting operations could not be loaded.'}finally{busy.value=false}}
async function saveDevice(){busy.value=true;try{await $api('/lighting/devices',{method:'POST',body:device});deviceOpen.value=false;await load()}catch(e){error.value=e?.data?.message||'Device could not be saved.'}finally{busy.value=false}}
async function saveZone(){busy.value=true;try{await $api('/lighting/zones',{method:'POST',body:zone});zoneOpen.value=false;await load()}catch(e){error.value=e?.data?.message||'Zone could not be saved.'}finally{busy.value=false}}
async function testDevice(d){busy.value=true;try{const r=await $api(`/lighting/devices/${d.id}/test`,{method:'POST'});alert(`${r.success?'Success':'Failed'}: ${label(r.status)} (${r.latency_ms}ms)`)}catch(e){error.value=e?.data?.message||'Safe connection test failed.'}finally{busy.value=false}}
function openOp(type,channel){operation.value=type;target.value=channel;op.reason='';operationOpen.value=true}
async function runOp(){busy.value=true;try{await $api(`/lighting/channels/${target.value.id}/${operation.value==='emergency'?'emergency-off':'override'}`,{method:'POST',body:{...op}});operationOpen.value=false;await load()}catch(e){error.value=e?.data?.message||'Operation failed.'}finally{busy.value=false}}
onMounted(load)
</script>
<template><div><div class="d-flex flex-wrap justify-space-between align-center gap-3 mb-6"><div><h3 class="text-h3">Court lighting</h3><p class="text-medium-emphasis">Safe dry-run automation, schedules, health, commands and financial reporting.</p></div><div class="d-flex gap-2"><VBtn variant="tonal" @click="deviceOpen=true">Add device</VBtn><VBtn @click="zoneOpen=true">Add zone</VBtn></div></div><VAlert v-if="error" type="error" closable class="mb-4">{{error}}</VAlert>
<VAlert v-if="data.settings" :type="data.settings.dry_run?'info':'warning'" class="mb-4"><strong>{{data.settings.dry_run?'Dry-run mode':'Live mode'}}</strong> · Automation {{data.settings.automation_enabled?'enabled':'disabled'}}. No hardware calls occur while disabled.</VAlert>
<VTabs v-model="tab" class="mb-4"><VTab value="schedule">Schedule</VTab><VTab value="devices">Devices & health</VTab><VTab value="zones">Zones & tariffs</VTab><VTab value="commands">Command queue</VTab><VTab value="alerts">Alerts</VTab><VTab value="reports">Reports</VTab></VTabs>
<VWindow v-model="tab"><VWindowItem value="schedule"><VCard><VCardTitle>Planned lighting intervals</VCardTitle><VTable><thead><tr><th>Channel</th><th>On</th><th>Off</th><th>Bookings</th><th>Status</th></tr></thead><tbody><tr v-for="i in data.intervals" :key="i.id"><td>{{i.channel?.device?.name}} · {{i.channel?.name}}</td><td>{{new Date(i.starts_at).toLocaleString()}}</td><td>{{new Date(i.ends_at).toLocaleString()}}</td><td>{{i.reservations?.map(r=>r.booking?.booking_reference).join(', ')}}</td><td>{{label(i.status)}}</td></tr></tbody></VTable></VCard></VWindowItem>
<VWindowItem value="devices"><VRow><VCol v-for="d in data.devices" :key="d.id" cols="12" md="6"><VCard><VCardTitle>{{d.name}}</VCardTitle><VCardText><p>{{d.code}} · {{d.provider}} · {{d.dry_run?'dry run':'live gated'}}</p><p>Health: {{label(d.last_health_status)}} · Credentials: {{d.credentials_configured?'configured':'not configured'}}</p><VChip v-for="c in d.channels" :key="c.id" class="me-2 mb-2">{{c.name}}: {{label(c.last_known_state)}}</VChip><div><VBtn size="small" variant="tonal" @click="testDevice(d)">Test connection</VBtn><VBtn v-for="c in d.channels" :key="`o${c.id}`" size="small" variant="text" @click="openOp('override',c)">Override {{c.channel_number}}</VBtn><VBtn v-for="c in d.channels" :key="`e${c.id}`" size="small" color="error" variant="text" @click="openOp('emergency',c)">Emergency off {{c.channel_number}}</VBtn></div></VCardText></VCard></VCol></VRow></VWindowItem>
<VWindowItem value="zones"><VCard><VTable><thead><tr><th>Zone</th><th>Facilities</th><th>Mode</th><th>Buffers</th><th>Status</th></tr></thead><tbody><tr v-for="z in data.zones" :key="z.id"><td>{{z.name}}<small class="d-block">{{z.code}}</small></td><td>{{z.facilities?.map(f=>f.name).join(', ')}}</td><td>{{label(z.provider_mode)}}</td><td>-{{z.pre_start_minutes}} / +{{z.post_end_minutes}} min</td><td>{{z.active?'active':'inactive'}}</td></tr></tbody></VTable></VCard></VWindowItem>
<VWindowItem value="commands"><VCard><VTable><thead><tr><th>Due</th><th>Device</th><th>Command</th><th>Status</th><th>Attempts</th><th>Safe result</th></tr></thead><tbody><tr v-for="c in data.commands" :key="c.id"><td>{{new Date(c.due_at).toLocaleString()}}</td><td>{{c.channel?.device?.name}}</td><td>{{label(c.command_type)}}</td><td>{{label(c.status)}}</td><td>{{c.attempt_count}}</td><td>{{label(c.safe_error_code||c.provider_result_code)}}</td></tr></tbody></VTable></VCard></VWindowItem>
<VWindowItem value="alerts"><VCard><VList><VListItem v-for="a in data.alerts" :key="a.id" :title="label(a.alert_type)" :subtitle="a.safe_message"><template #append><VChip :color="a.severity==='critical'?'error':'warning'">{{a.status}}</VChip></template></VListItem></VList></VCard></VWindowItem>
<VWindowItem value="reports"><VRow><VCol cols="12" md="4"><VCard><VCardTitle>Reservations</VCardTitle><VCardText class="text-h3">{{data.reservations.length}}</VCardText></VCard></VCol><VCol cols="12" md="4"><VCard><VCardTitle>Lighting booked</VCardTitle><VCardText class="text-h3">{{money(data.reservations.reduce((s,r)=>s+r.amount,0))}}</VCardText></VCard></VCol><VCol cols="12" md="4"><VCard><VCardTitle>Open alerts</VCardTitle><VCardText class="text-h3">{{data.alerts.filter(a=>a.status==='open').length}}</VCardText></VCard></VCol></VRow></VWindowItem></VWindow>
<VDialog v-model="deviceOpen" max-width="680"><VCard><VCardTitle>Add safe lighting device</VCardTitle><VCardText><VTextField v-model="device.name" label="Name"/><VTextField v-model="device.code" label="Code"/><VSelect v-model="device.provider" :items="['dry_run','manual','shelly']" label="Provider"/><VTextField v-model="device.network_host" label="Verified local host (optional in dry run)"/><VTextField v-model="device.username" label="Username (write only)"/><VTextField v-model="device.password" type="password" label="Password (write only)"/><VSwitch v-model="device.dry_run" label="Dry run"/><VAlert type="info" variant="tonal">Live operation remains safety-gated. Do not configure a device until its channel has been independently verified by a qualified electrician.</VAlert></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="deviceOpen=false">Close</VBtn><VBtn :loading="busy" @click="saveDevice">Save</VBtn></VCardActions></VCard></VDialog>
<VDialog v-model="zoneOpen" max-width="680"><VCard><VCardTitle>Add lighting zone</VCardTitle><VCardText><VTextField v-model="zone.name" label="Name"/><VTextField v-model="zone.code" label="Code"/><VTextField v-model.number="zone.venue_id" type="number" label="Venue ID"/><VTextField v-model.number="zone.sport_code_id" type="number" label="Sport code ID"/><VTextField v-model.number="zone.lighting_device_channel_id" type="number" label="Verified channel ID"/><VSelect v-model="zone.provider_mode" :items="['dry_run','manual','shelly']" label="Provider mode"/><VRow><VCol><VTextField v-model.number="zone.pre_start_minutes" type="number" label="Pre-start minutes"/></VCol><VCol><VTextField v-model.number="zone.post_end_minutes" type="number" label="Post-end minutes"/></VCol></VRow></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="zoneOpen=false">Close</VBtn><VBtn :loading="busy" @click="saveZone">Save</VBtn></VCardActions></VCard></VDialog>
<VDialog v-model="operationOpen" max-width="580"><VCard><VCardTitle>{{operation==='emergency'?'Emergency switch-off':'Timed manual override'}}</VCardTitle><VCardText><VSelect v-if="operation!=='emergency'" v-model="op.state" :items="['on','off']" label="State"/><VTextField v-if="operation!=='emergency'" v-model.number="op.minutes" type="number" label="Duration (minutes)"/><VTextarea v-model="op.reason" label="Reason"/><VAlert :type="operation==='emergency'?'error':'warning'" variant="tonal">{{operation==='emergency'?'Pending switch-ons will be superseded. Bookings are listed but are not automatically refunded.':'Normal automation is suspended until this override expires.'}}</VAlert></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="operationOpen=false">Close</VBtn><VBtn :color="operation==='emergency'?'error':'primary'" :disabled="op.reason.length<3" @click="runOp">Confirm</VBtn></VCardActions></VCard></VDialog></div></template>
